#include <stdio.h>
int power(int base, int exp) {
    if (exp == 0) return 1;
    return base * power(base, exp - 1);
}
int main() {
    int result = 0;
    for (int i = 1; i <= 3; i++) {
        result += power(2, i);
    }
    printf("%d", result);
    return 0;
}

