#include <stdio.h>
struct Node {
    int value;
    struct Node* next;
};
void printReverse(struct Node* node) {
    if (node == NULL) return;
    printReverse(node->next);
    printf("%d", node->value);
}
int main() {
    struct Node n3 = {3, NULL};
    struct Node n2 = {2, &n3};
    struct Node n1 = {1, &n2};
    printReverse(&n1);
    return 0;
}

