#include <stdio.h>
void swap(int *a, int *b){
    int temp = *a;
    *a = *b;
    *b = temp;
}
void main(){
    int x = 10, y = 20;
    int *px = &x, *py = &y;
    swap(px, py);
    printf("%d %d\n", x, y);
    printf("%d %d\n", *px, *py);
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>

int countVowels(char* str){
    int cnt = 0;
    while(*str != '\0'){
        char c = tolower(*str);
        if(c=='a'||c=='e'||c=='i'||c=='o'||c=='u') cnt++;
        str++;
    }
    return cnt;
}

int main(int argc, char* argv[]){
    char str[100] = "ProgrammingExam";
    printf("%d", countVowels(str));
    return 0;
}

